#!/usr/bin/env bash
# Generated by Context.Claude's ClaudeIntegrationInstaller — do not edit by hand.
# Re-run the installer (`context claude install`) to regenerate. This script fails open:
# any error here must never block Claude Code, so it never uses `set -e`.

INPUT="$(cat)"
# Fallback only matters when CLAUDE_PROJECT_DIR isn't set (Claude Code always sets it
# for hooks today, but don't rely on that). The script lives at
# <project-root>/.claude/hooks/<name>.sh, so reaching <project-root> needs two levels
# up from dirname(script), not one.
PROJECT_DIR="${CLAUDE_PROJECT_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}"
CONFIG_FILE="$PROJECT_DIR/.claude/context-platform.local.json"
LOG_FILE="$PROJECT_DIR/.claude/hooks.log"

log_error() {
    printf '%s [post-tool-use] %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$1" >> "$LOG_FILE" 2>/dev/null
}

[ -f "$CONFIG_FILE" ] || exit 0
# A config this user can't read (e.g. written 0600 by a host running as another user)
# used to fail silently here, since grep's error is discarded below.
if [ ! -r "$CONFIG_FILE" ]; then
    log_error "config not readable by $(id -un 2>/dev/null): $CONFIG_FILE"
    exit 0
fi

TOKEN="$(grep -o '"bearerToken"[[:space:]]*:[[:space:]]*"[^"]*"' "$CONFIG_FILE" 2>/dev/null | sed -E 's/.*:[[:space:]]*"([^"]*)"/\1/')"
PORT="$(grep -o '"port"[[:space:]]*:[[:space:]]*[0-9]\+' "$CONFIG_FILE" 2>/dev/null | grep -o '[0-9]\+')"
if [ -z "$TOKEN" ]; then
    log_error "no bearerToken in $CONFIG_FILE"
    exit 0
fi
PORT="${PORT:-47923}"

# Same host-resolution problem/heuristic as OllamaHostFallbackHandler: 127.0.0.1 always
# works bare-metal (and for a container whose port is published back to the host's own
# loopback), but a hook script running INSIDE a container needs a different address to
# reach a Context.Dashboard.Server that lives outside it.
HOSTS=(127.0.0.1)
if [ -f /.dockerenv ] || [ "${DOTNET_RUNNING_IN_CONTAINER:-}" = "true" ] || [ "${CONTEXT_RUNNING_IN_CONTAINER:-}" = "true" ]; then
    HOSTS+=(host.docker.internal 172.17.0.1)
fi

# $INPUT (a tool's full input/response JSON) can be large enough to blow past a
# platform's command-line length limit if passed to curl as a literal argument --
# Windows' ~32K CreateProcess limit in particular, which mingw64 curl.exe is subject to
# even though bash itself has no such limit. Writing it to a temp file and using
# curl's `--data-binary @file` sidesteps argv entirely, regardless of platform.
TMP_INPUT="$(mktemp 2>/dev/null)" || exit 0
trap 'rm -f "$TMP_INPUT"' EXIT
printf '%s' "$INPUT" > "$TMP_INPUT" 2>/dev/null

RESPONSE=""
LAST_ERROR=""
for HOST in "${HOSTS[@]}"; do
    OUTPUT="$(curl -fsS -m 2 -X POST "http://${HOST}:${PORT}/hooks/post-tool-use" \
        -H "Authorization: Bearer $TOKEN" \
        -H "Content-Type: application/json" \
        --data-binary @"$TMP_INPUT" 2>&1)"
    if [ $? -eq 0 ]; then
        RESPONSE="$OUTPUT"
        LAST_ERROR=""
        break
    fi
    LAST_ERROR="host ${HOST}:${PORT}: $OUTPUT"
done

if [ -n "$LAST_ERROR" ]; then
    log_error "unreachable ($LAST_ERROR)"
    exit 0
fi
[ -n "$RESPONSE" ] || exit 0

CONTEXT="$(printf '%s' "$RESPONSE" | grep -o '"additionalContext"[[:space:]]*:[[:space:]]*"\([^"\\]\|\\.\)*"' 2>/dev/null | sed -E 's/^"additionalContext"[[:space:]]*:[[:space:]]*"//; s/"$//')"
[ -n "$CONTEXT" ] || exit 0

printf '%b' "$CONTEXT" | sed 's/\\"/"/g'
exit 0
